mapper.update:
update iam_api_instance_idempotency_records set status='COMPLETED',response_http_status=#{row.httpStatus},response_content_type=#{row.contentType},
  response_body=#{row.responseBody},completed_at=#{row.completedAt}
where scope_id=#{row.scopeId} and actor_id=#{row.actorId} and operation=#{row.operation} and idempotency_key=#{row.key} and status='IN_PROGRESS'

update iam_api_tenant_idempotency_records set status='COMPLETED',response_http_status=#{row.httpStatus},response_content_type=#{row.contentType},
  response_body=#{row.responseBody},completed_at=#{row.completedAt}
where tenant_id=#{row.tenantId} and actor_id=#{row.actorId} and operation=#{row.operation} and idempotency_key=#{row.key} and status='IN_PROGRESS'

mapper.select:
select subject_type as "subjectType",subject_id as "subjectId",requested_tenant_id as "requestedTenantId",authenticated_at as "authenticatedAt",version
from auth_login_challenges
where challenge_id=#{challengeId}
  and challenge_hash=#{challengeHash}
  and status='ACTIVE'
  and expires_at>#{at}

select u.user_id as "userId",u.username,u.email,u.display_name as "displayName",u.status,
  u.creation_mode as "creationMode",u.created_at as "createdAt",u.updated_at as "updatedAt",u.version
from iam_users u where u.user_id=#{userId}

select distinct u.user_id as "userId",u.username,u.email,u.display_name as "displayName",u.status,u.creation_mode as "creationMode",u.created_at as "createdAt",u.updated_at as "updatedAt",u.version, case when federated.provider_type is not null and cred.subject_id is not null then concat('LOCAL+',federated.provider_type) when federated.provider_type is not null then federated.provider_type else 'LOCAL' end as "authenticationMethod", case when u.status='LOCKED' or (sec.locked_until is not null and sec.locked_until>now()) then 'LOCKED' when u.status='SUSPENDED' then 'SUSPENDED' when u.status in('DISABLED','DELETED') then 'DISABLED' when u.status in('ACTIVE','PENDING_ACTIVATION','PASSWORD_RESET_REQUIRED','MFA_ENROLLMENT_REQUIRED') and federated.provider_type is not null then 'SSO_MANAGED' when cred.subject_id is null or u.status in('PENDING_ACTIVATION','PASSWORD_RESET_REQUIRED') then 'SETUP_REQUIRED' when u.status='MFA_ENROLLMENT_REQUIRED' or coalesce(mfa.status,'')='PENDING' then 'MFA_REQUIRED' when u.status='ACTIVE' and cred.subject_id is not null and not cred.must_change then 'READY' else 'SETUP_REQUIRED' end as "signInState", case when cred.subject_id is null then 'NOT_CONFIGURED' when cred.must_change then 'CHANGE_REQUIRED' else 'CONFIGURED' end as "passwordState", case when mfa.method_id is null then 'NOT_ENROLLED' when mfa.status='ACTIVE' then 'ACTIVE' else 'PENDING' end as "mfaState", coalesce(case when delivery.expires_at<=now() and delivery.delivery_status in('ISSUED','QUEUED','DELIVERED') then 'EXPIRED' else delivery.delivery_status end,'NOT_ISSUED') as "deliveryStatus", case when not exists ( select 1 from rbac_principal_role_bindings access_b join rbac_roles access_r on access_r.role_id=access_b.role_id and (access_r.tenant_id=#{tenantId} or access_r.tenant_id is null) and access_r.status='ACTIVE' where access_b.tenant_id=#{tenantId} and access_b.status='ACTIVE' and access_b.effective_at<=now() and (access_b.expires_at is null or access_b.expires_at>now()) and ((access_b.principal_type='USER' and access_b.principal_id=u.user_id) or (access_b.principal_type='DEPARTMENT' and exists (select 1 from org_department_memberships adm where adm.tenant_id=#{tenantId} and adm.user_id=u.user_id and adm.department_id=access_b.principal_id and adm.status='ACTIVE' and adm.effective_at<=now() and (adm.expires_at is null or adm.expires_at>now()))) or (access_b.principal_type='GROUP' and exists (select 1 from org_group_memberships agm where agm.tenant_id=#{tenantId} and agm.user_id=u.user_id and agm.group_id=access_b.principal_id and agm.status='ACTIVE' and agm.effective_at<=now() and (agm.expires_at is null or agm.expires_at>now())))) ) then 'NO_RESPONSIBILITY' when not exists ( select 1 from rbac_principal_role_bindings access_b join rbac_roles access_r on access_r.role_id=access_b.role_id and (access_r.tenant_id=#{tenantId} or access_r.tenant_id is null) and access_r.status='ACTIVE' join rbac_role_permissions access_rp on access_rp.role_id=access_r.role_id and access_rp.tenant_id is not distinct from access_r.tenant_id where access_b.tenant_id=#{tenantId} and access_b.status='ACTIVE' and access_b.effective_at<=now() and (access_b.expires_at is null or access_b.expires_at>now()) and ((access_b.principal_type='USER' and access_b.principal_id=u.user_id) or (access_b.principal_type='DEPARTMENT' and exists (select 1 from org_department_memberships adm where adm.tenant_id=#{tenantId} and adm.user_id=u.user_id and adm.department_id=access_b.principal_id and adm.status='ACTIVE' and adm.effective_at<=now() and (adm.expires_at is null or adm.expires_at>now()))) or (access_b.principal_type='GROUP' and exists (select 1 from org_group_memberships agm where agm.tenant_id=#{tenantId} and agm.user_id=u.user_id and agm.group_id=access_b.principal_id and agm.status='ACTIVE' and agm.effective_at<=now() and (agm.expires_at is null or agm.expires_at>now())))) ) then 'NO_EFFECTIVE_PERMISSION' else 'READY' end as "accessReadiness", coalesce(( select string_agg(distinct access_r.role_code, ', ' order by access_r.role_code) from rbac_principal_role_bindings access_b join rbac_roles access_r on access_r.role_id=access_b.role_id and (access_r.tenant_id=#{tenantId} or access_r.tenant_id is null) and access_r.status='ACTIVE' where access_b.tenant_id=#{tenantId} and access_b.status='ACTIVE' and access_b.effective_at<=now() and (access_b.expires_at is null or access_b.expires_at>now()) and ((access_b.principal_type='USER' and access_b.principal_id=u.user_id) or (access_b.principal_type='DEPARTMENT' and exists (select 1 from org_department_memberships adm where adm.tenant_id=#{tenantId} and adm.user_id=u.user_id and adm.department_id=access_b.principal_id and adm.status='ACTIVE' and adm.effective_at<=now() and (adm.expires_at is null or adm.expires_at>now()))) or (access_b.principal_type='GROUP' and exists (select 1 from org_group_memberships agm where agm.tenant_id=#{tenantId} and agm.user_id=u.user_id and agm.group_id=access_b.principal_id and agm.status='ACTIVE' and agm.effective_at<=now() and (agm.expires_at is null or agm.expires_at>now())))) ),'') as "responsibilitySummary" from org_tenant_memberships m join iam_users u on u.user_id=m.user_id left join auth_password_credentials cred on cred.subject_type='HUMAN_USER' and cred.subject_id=u.user_id left join auth_subject_security_states sec on sec.subject_type='HUMAN_USER' and sec.subject_id=u.user_id left join lateral (select method_id,status from auth_mfa_methods x where x.subject_type='HUMAN_USER' and x.subject_id=u.user_id and x.status in('ACTIVE','PENDING') order by case when x.status='ACTIVE' then 0 else 1 end,x.enrolled_at desc limit 1) mfa on true left join lateral (select l.provider_type from iam_identity_credential_links l join iam_authentication_providers p on p.tenant_id=l.provider_tenant_id and p.provider_id=l.provider_id where l.provider_tenant_id=#{tenantId} and l.subject_id=u.user_id and l.status='ACTIVE' and p.status='ACTIVE' and p.provider_type='OIDC' order by p.provider_code limit 1) federated on true left join lateral (select delivery_status,expires_at from iam_identity_activation_deliveries x where x.tenant_id=#{tenantId} and x.user_id=u.user_id order by x.issued_at desc limit 1) delivery on true where m.tenant_id=#{tenantId} and m.status<>'REMOVED' and (
exists ( select 1 from org_department_memberships visible_dm where visible_dm.tenant_id=#{tenantId} and visible_dm.user_id=u.user_id and visible_dm.department_id in #{id} and visible_dm.status='ACTIVE' and visible_dm.effective_at<=now() and (visible_dm.expires_at is null or visible_dm.expires_at>now()) ) or exists ( select 1 from org_group_memberships visible_gm where visible_gm.tenant_id=#{tenantId} and visible_gm.user_id=u.user_id and visible_gm.group_id in #{id} and visible_gm.status='ACTIVE' and visible_gm.effective_at<=now() and (visible_gm.expires_at is null or visible_gm.expires_at>now()) )
exists ( select 1 from org_department_memberships visible_dm where visible_dm.tenant_id=#{tenantId} and visible_dm.user_id=u.user_id and visible_dm.department_id in #{id} and visible_dm.status='ACTIVE' and visible_dm.effective_at<=now() and (visible_dm.expires_at is null or visible_dm.expires_at>now()) )
exists ( select 1 from org_group_memberships visible_gm where visible_gm.tenant_id=#{tenantId} and visible_gm.user_id=u.user_id and visible_gm.group_id in #{id} and visible_gm.status='ACTIVE' and visible_gm.effective_at<=now() and (visible_gm.expires_at is null or visible_gm.expires_at>now()) )
false
) and (#{membershipStatus} is null or #{membershipStatus}='' or m.status=#{membershipStatus}) and (#{afterUserId} is null or #{afterUserId}='' or u.user_id>#{afterUserId}) and (#{text} is null or #{text}='' or lower(u.username) like concat('%',lower(#{text}),'%') or lower(u.display_name) like concat('%',lower(#{text}),'%') or lower(coalesce(u.email,'')) like concat('%',lower(#{text}),'%')) and (#{status} is null or #{status}='' or u.status=#{status}) and (#{roleId} is null or #{roleId}='' or exists ( select 1 from rbac_principal_role_bindings b where b.tenant_id=#{tenantId} and b.principal_type='USER' and b.principal_id=u.user_id and b.role_id=#{roleId} and b.status='ACTIVE' and b.effective_at<=now() and (b.expires_at is null or b.expires_at>now()) )) and (#{departmentId} is null or #{departmentId}='' or (#{departmentId}='__UNASSIGNED__' and not exists ( select 1 from org_department_memberships primary_dm where primary_dm.tenant_id=#{tenantId} and primary_dm.user_id=u.user_id and primary_dm.is_primary and primary_dm.status='ACTIVE' and primary_dm.effective_at<=now() and (primary_dm.expires_at is null or primary_dm.expires_at>now()) )) or (#{departmentId}<>'__UNASSIGNED__' and exists ( select 1 from org_department_memberships dm where dm.tenant_id=#{tenantId} and dm.user_id=u.user_id and dm.department_id=#{departmentId} and dm.status='ACTIVE' and dm.effective_at<=now() and (dm.expires_at is null or dm.expires_at>now()) )) ) and (#{groupId} is null or #{groupId}='' or exists ( select 1 from org_group_memberships gm where gm.tenant_id=#{tenantId} and gm.user_id=u.user_id and gm.group_id=#{groupId} and gm.status='ACTIVE' and gm.effective_at<=now() and (gm.expires_at is null or gm.expires_at>now()) )) order by u.user_id limit #{limit}

mapper.update:
update iam_identity_activation_deliveries
   set delivery_status=#{row.deliveryStatus},delivered_at=#{row.deliveredAt},failed_at=#{row.failedAt},failure_code=#{row.failureCode},version=version+1
 where tenant_id=#{row.tenantId} and delivery_id=#{row.deliveryId}

mapper.select:
select tenant_id as "tenantId",department_id as "departmentId",department_code as code,department_name as name,parent_department_id as "parentDepartmentId",manager_user_id as "managerUserId",status,display_order as "displayOrder",created_at as "createdAt",updated_at as "updatedAt",version
from departments where tenant_id=#{tenantId}
  and (#{text} is null or #{text}='' or lower(department_code) like concat('%',lower(#{text}),'%') or lower(department_name) like concat('%',lower(#{text}),'%'))
  and (((#{status} is null or #{status}='') and status<>'DELETED') or status=#{status})
order by display_order,department_id offset #{offset} limit #{limit}

select tenant_id as "tenantId",department_id as "departmentId",department_code as code,department_name as name,parent_department_id as "parentDepartmentId",manager_user_id as "managerUserId",status,display_order as "displayOrder",created_at as "createdAt",updated_at as "updatedAt",version
from departments
where tenant_id=#{tenantId}
  and department_id in
  #{id}
  and (#{text} is null or #{text}='' or lower(department_code) like concat('%',lower(#{text}),'%') or lower(department_name) like concat('%',lower(#{text}),'%'))
  and (((#{status} is null or #{status}='') and status<>'DELETED') or status=#{status})
order by display_order,department_id offset #{offset} limit #{limit}

select tenant_id as "tenantId",group_id as "groupId",group_code as code,group_name as name,group_type as type,parent_group_id as "parentGroupId",owner_department_id as "ownerDepartmentId",status,description,created_at as "createdAt",updated_at as "updatedAt",version
from organization_groups where tenant_id=#{tenantId}
  and (#{text} is null or #{text}='' or lower(group_code) like concat('%',lower(#{text}),'%') or lower(group_name) like concat('%',lower(#{text}),'%'))
  and (#{type} is null or #{type}='' or group_type=#{type})
  and (((#{status} is null or #{status}='') and status<>'DELETED') or status=#{status})
order by group_id offset #{offset} limit #{limit}

select tenant_id as "tenantId",group_id as "groupId",group_code as code,group_name as name,group_type as type,parent_group_id as "parentGroupId",owner_department_id as "ownerDepartmentId",status,description,created_at as "createdAt",updated_at as "updatedAt",version
from organization_groups
where tenant_id=#{tenantId}
  and group_id in
  #{id}
  and (#{text} is null or #{text}='' or lower(group_code) like concat('%',lower(#{text}),'%') or lower(group_name) like concat('%',lower(#{text}),'%'))
  and (#{type} is null or #{type}='' or group_type=#{type})
  and (((#{status} is null or #{status}='') and status<>'DELETED') or status=#{status})
order by group_id offset #{offset} limit #{limit}

select membership_id as "membershipId",'TENANT' as "membershipType",tenant_id as "tenantId",user_id as "userId",tenant_id as "resourceId",membership_source as role,status,default_tenant as "primary",joined_at as "effectiveAt",expires_at as "expiresAt",version,employee_id as "employeeId"
from org_tenant_memberships where tenant_id=#{tenantId} and user_id=#{userId} and (#{afterMembershipId} is null or #{afterMembershipId}='' or membership_id>#{afterMembershipId})
union all
select membership_id,'DEPARTMENT',tenant_id,user_id,department_id,membership_type,status,is_primary,effective_at,expires_at,version,null::varchar as "employeeId"
from org_department_memberships where tenant_id=#{tenantId} and user_id=#{userId} and (#{afterMembershipId} is null or #{afterMembershipId}='' or membership_id>#{afterMembershipId})
union all
select membership_id,'GROUP',tenant_id,user_id,group_id,membership_role,status,false,effective_at,expires_at,version,null::varchar as "employeeId"
from org_group_memberships where tenant_id=#{tenantId} and user_id=#{userId} and (#{afterMembershipId} is null or #{afterMembershipId}='' or membership_id>#{afterMembershipId})
order by "membershipId" limit #{limit}

select role_id as "roleId",coalesce(tenant_id,'') as "tenantId",role_code as "roleCode",role_name as "roleName",description,role_type as "roleType",status,system_managed as "systemManaged",created_at as "createdAt",updated_at as "updatedAt",version
from rbac_roles where (tenant_id=#{tenantId} or tenant_id is null)
  and (#{text} is null or #{text}='' or lower(role_code) like concat('%',lower(#{text}),'%') or lower(role_name) like concat('%',lower(#{text}),'%'))
  and (#{type} is null or #{type}='' or role_type=#{type}) and (((#{status} is null or #{status}='') and status<>'DELETED') or status=#{status})
order by role_code offset #{offset} limit #{limit}

select role_id as "roleId",'' as "tenantId",role_code as "roleCode",role_name as "roleName",description,role_type as "roleType",status,system_managed as "systemManaged",created_at as "createdAt",updated_at as "updatedAt",version
from rbac_roles where tenant_id is null and role_type in ('SYSTEM_ROLE','CUSTOM_PLATFORM_ROLE')
  and (#{text} is null or #{text}='' or lower(role_code) like concat('%',lower(#{text}),'%') or lower(role_name) like concat('%',lower(#{text}),'%'))
  and (#{type} is null or #{type}='' or role_type=#{type}) and (((#{status} is null or #{status}='') and status<>'DELETED') or status=#{status})
order by role_code offset #{offset} limit #{limit}

select permission_code as "permissionCode",permission_code as "displayName",description,array_to_string(allowed_scope_types,chr(31)) as "allowedScopesCsv",system_managed as "systemManaged"
from permission_definitions where active=true and lifecycle in ('ACTIVE','DEPRECATED')
  and (#{text} is null or #{text}='' or lower(permission_code) like concat('%',lower(#{text}),'%') or lower(description) like concat('%',lower(#{text}),'%'))
  and (#{scopeType} is null or #{scopeType}='' or #{scopeType}=any(allowed_scope_types))
order by permission_code offset #{offset} limit #{limit}

select binding_id as "bindingId",principal_type as "principalType",principal_id as "principalId",role_id as "roleId",scope_type as "scopeType",scope_id as "scopeId",effective_at as "effectiveAt",expires_at as "expiresAt",status,version
from rbac_principal_role_bindings where ((#{tenantId} is null and tenant_id is null) or tenant_id=#{tenantId})
  and (#{roleId} is null or #{roleId}='' or role_id=#{roleId})
  and (#{principalId} is null or #{principalId}='' or principal_id=#{principalId})
  and (#{afterBindingId} is null or #{afterBindingId}='' or binding_id>#{afterBindingId})
order by binding_id limit #{limit}

select session_id as "sessionId",subject_type as "subjectType",subject_id as "subjectId",tenant_id as "tenantId",array_to_string(authentication_methods,chr(31)) as "methodsCsv",created_at as "createdAt",last_seen_at as "lastSeenAt",idle_expires_at as "idleExpiresAt",absolute_expires_at as "absoluteExpiresAt",ip_address as "ipAddress",user_agent as "userAgent",status,version
from auth_tenant_sessions where tenant_id=#{tenantId} and (#{subjectId} is null or #{subjectId}='' or subject_id=#{subjectId})
  and (#{afterSessionId} is null or #{afterSessionId}='' or session_id>#{afterSessionId})
order by session_id limit #{limit}

select tenant_id as "tenantId",credential_id as "credentialId",service_account_id as "serviceAccountId",credential_type as "credentialType",credential_name as name,client_id as "clientId",last4,status,issued_at as "issuedAt",expires_at as "expiresAt",last_used_at as "lastUsedAt",rotation_grace_expires_at as "rotationGraceExpiresAt",use_count as "useCount",version
from token_service_account_credentials where tenant_id=#{tenantId} and service_account_id=#{serviceAccountId} and (#{status} is null or #{status}='' or status=#{status}) and (#{afterId} is null or #{afterId}='' or credential_id>#{afterId})
order by credential_id limit #{limit}

select token_id as "tokenId",token_type as "tokenType",principal_type as "principalType",principal_id as "principalId",token_name as name,token_prefix as prefix,last4,status,issued_at as "issuedAt",expires_at as "expiresAt",last_used_at as "lastUsedAt",version
from token_access_tokens where tenant_id=#{tenantId} and (#{principalId} is null or #{principalId}='' or principal_id=#{principalId}) and (#{status} is null or #{status}='' or status=#{status}) and (#{afterId} is null or #{afterId}='' or token_id>#{afterId})
order by token_id limit #{limit}

select decision_id as "eventId",'AUTHORIZATION_DECISION' as "eventType",principal_type as "actorType",principal_id as "actorId",coalesce(resource_type,'') as "targetType",coalesce(resource_id,'') as "targetId",coalesce(tenant_id,'') as "tenantId",permission_point as permission,decision_id as "decisionId",coalesce(correlation_id,'') as "correlationId",reason_code as reason,decided_at as "occurredAt"
from rbac_decision_audits where tenant_id=#{tenantId}
  and (#{eventType} is null or #{eventType}='' or #{eventType}='AUTHORIZATION_DECISION')
  and (#{actorId} is null or #{actorId}='' or principal_id=#{actorId}) and (#{targetId} is null or #{targetId}='' or resource_id=#{targetId})
  and (#{afterEventId} is null or #{afterEventId}='' or decision_id>#{afterEventId})
order by decision_id limit #{limit}

mapper.update:
update iam_identity_credential_links
   set last_authenticated_at=#{authenticatedAt},updated_at=#{authenticatedAt},updated_by=#{updatedBy},version=version+1
 where credential_link_id=#{credentialLinkId} and status='ACTIVE' and version=#{expectedVersion}

update iam_identity_credential_links
   set status='REPLACED',replacement_required=false,replaced_at=#{replacedAt},updated_at=#{replacedAt},updated_by=#{updatedBy},version=version+1
 where credential_link_id=#{credentialLinkId} and status='ACTIVE' and version=#{expectedVersion}

mapper.select:
select l.credential_link_id as "credentialLinkId",l.provider_tenant_id as "tenantId",l.provider_id as "providerId",p.provider_code as "providerCode",l.provider_type as "providerType",coalesce(l.issuer_uri,'') as "issuerUri",l.provider_subject as "externalSubject",coalesce(l.upstream_username,'') as "upstreamUsername",coalesce(l.upstream_email,'') as "upstreamEmail",l.upstream_email_verified as "upstreamEmailVerified",l.subject_id as "userId",l.canonical_username as "canonicalUsername",l.status,l.last_authenticated_at as "lastAuthenticatedAt",l.version
  from iam_identity_credential_links l join iam_authentication_providers p on p.tenant_id=l.provider_tenant_id and p.provider_id=l.provider_id
 where l.provider_tenant_id=#{tenantId} and l.credential_link_id=#{credentialLinkId}

select u.user_id as "userId",u.username,u.status,u.version
  from iam_users u join org_tenant_memberships m on m.user_id=u.user_id and m.tenant_id=#{tenantId}
 where u.normalized_email=#{normalizedEmail}
   and u.status in('ACTIVE','PENDING_ACTIVATION','PASSWORD_RESET_REQUIRED','MFA_ENROLLMENT_REQUIRED')
   and m.status='ACTIVE' and m.effective_at<=now() and (m.expires_at is null or m.expires_at>now())

select a.tenant_id as "tenantId",a.attempt_id as "attemptId",a.provider_id as "providerId",a.state_hash as "stateHash",a.nonce_hash as "nonceHash",a.redirect_path as "redirectPath",a.status,a.issued_at as "issuedAt",a.expires_at as "expiresAt",a.version,
       p.provider_code as "providerCode",p.provider_type as "providerType",p.display_name as "displayName",p.status as "providerStatus",p.issuer_uri as "issuerUri",p.client_id as "clientId",p.client_secret_ref as "clientSecretRef",array_to_string(p.scopes,chr(31)) as "scopesCsv",p.subject_claim as "subjectClaim",p.username_claim as "usernameClaim",p.email_claim as "emailClaim",p.display_name_claim as "displayNameClaim",p.amr_claim as "amrClaim",p.acr_claim as "acrClaim",p.upstream_mfa_mode as "upstreamMfaMode",array_to_string(p.trusted_amr_values,chr(31)) as "trustedAmrValuesCsv",array_to_string(p.trusted_acr_values,chr(31)) as "trustedAcrValuesCsv",p.link_mode as "linkMode",p.jit_mode as "jitMode",p.authorization_enabled as "authorizationEnabled",p.version as "providerVersion"
  from iam_oidc_login_attempts a join iam_authentication_providers p on p.tenant_id=a.tenant_id and p.provider_id=a.provider_id where a.state_hash=#{stateHash}
